export const dictionaries: Record<Locale, Messages> = {
  es,
  en,
  pt,
  fr,
  ar,
  ru,
  zh,
  ja,
  it,
  de,
};

export function isRtlLocale(locale: Locale): boolean {
  return locale === "ar";
}

export function isLocale(value: string | null | undefined): value is Locale {
  return (
    value === "es" ||
    value === "en" ||
    value === "pt" ||
    value === "fr" ||
    value === "ar" ||
    value === "ru" ||
    value === "zh" ||
    value === "ja" ||
    value === "it" ||
    value === "de"
  );
}
